<?php $this->layout('layouts/studio'); ?>
<section class="studio-page-head"><div><p class="studio-eyebrow">Central de ajuda</p><h1 class="studio-page-title"><?= $category?'Editar categoria':'Nova categoria' ?></h1><p class="studio-page-description">Organize as matérias em assuntos fáceis de localizar.</p></div><a class="studio-btn" href="<?= url('/studio/support') ?>">Voltar</a></section>
